create extension if not exists "pgcrypto";
create type user_role as enum ('employee','quality','executor','manager','admin');
create table departments(id uuid primary key default gen_random_uuid(),name text not null,code text unique not null,manager_id uuid,is_active boolean default true,created_at timestamptz default now());
create table profiles(id uuid primary key references auth.users on delete cascade,full_name text not null,email text not null,role user_role not null default 'employee',department_id uuid references departments,position text,avatar_url text,is_active boolean default true,created_at timestamptz default now());
alter table departments add constraint departments_manager_fk foreign key(manager_id) references profiles(id);
create table products(id uuid primary key default gen_random_uuid(),name text not null,code text unique,is_active boolean default true);
create table deviations(id uuid primary key default gen_random_uuid(),deviation_number text unique not null,title text not null,description text,detected_at timestamptz,registered_at timestamptz default now(),created_by uuid references profiles,department_id uuid references departments,production_area text,equipment text,product_id uuid references products,batch_number text,expected_process text,actual_situation text,immediate_actions text,product_impact text,safety_impact text,severity text,status text,responsible_user_id uuid references profiles,investigation_due_date date,closure_due_date date,closed_at timestamptz,final_conclusion text,is_archived boolean default false,created_at timestamptz default now(),updated_at timestamptz default now());
create table investigations(id uuid primary key default gen_random_uuid(),deviation_id uuid references deviations not null,lead_user_id uuid references profiles,facts text,chronology text,preliminary_conclusion text,final_conclusion text,root_cause_method text,root_cause text,started_at timestamptz,completed_at timestamptz);
create table investigation_members(id uuid primary key default gen_random_uuid(),investigation_id uuid references investigations,user_id uuid references profiles,responsibility text);
create table root_cause_items(id uuid primary key default gen_random_uuid(),investigation_id uuid references investigations,category text,question text,answer text,sequence_number int);
create table capa_actions(id uuid primary key default gen_random_uuid(),deviation_id uuid references deviations,action_type text,title text not null,description text,responsible_user_id uuid references profiles,department_id uuid references departments,due_date date,completed_at timestamptz,status text,executor_comment text,quality_comment text,effectiveness_status text,is_archived boolean default false);
create table effectiveness_checks(id uuid primary key default gen_random_uuid(),capa_action_id uuid references capa_actions,method text,checked_by uuid references profiles,check_date date,result text,before_value text,after_value text,is_effective boolean,deviation_repeated boolean,comment text);
create table attachments(id uuid primary key default gen_random_uuid(),deviation_id uuid references deviations,capa_action_id uuid references capa_actions,uploaded_by uuid references profiles,file_name text,file_url text,file_type text,file_size bigint,created_at timestamptz default now());
create table comments(id uuid primary key default gen_random_uuid(),deviation_id uuid references deviations,author_id uuid references profiles,parent_comment_id uuid references comments,content text,created_at timestamptz default now(),updated_at timestamptz default now(),is_archived boolean default false);
create table approvals(id uuid primary key default gen_random_uuid(),deviation_id uuid references deviations,stage text,approver_id uuid references profiles,decision text,comment text,decided_at timestamptz);
create table notifications(id uuid primary key default gen_random_uuid(),user_id uuid references profiles,type text,title text,message text,related_entity_type text,related_entity_id uuid,is_read boolean default false,created_at timestamptz default now());
create table audit_logs(id bigint generated always as identity primary key,user_id uuid references profiles,entity_type text,entity_id uuid,action text,old_value jsonb,new_value jsonb,ip_address inet,created_at timestamptz default now());
alter table profiles enable row level security; alter table deviations enable row level security; alter table investigations enable row level security; alter table capa_actions enable row level security; alter table attachments enable row level security; alter table comments enable row level security; alter table notifications enable row level security; alter table audit_logs enable row level security;
create policy "profile self or privileged" on profiles for select using (id=auth.uid() or exists(select 1 from profiles p where p.id=auth.uid() and p.role in ('quality','manager','admin')));
create policy "deviation role visibility" on deviations for select using (created_by=auth.uid() or responsible_user_id=auth.uid() or exists(select 1 from profiles p where p.id=auth.uid() and p.role in ('quality','admin')) or exists(select 1 from profiles p where p.id=auth.uid() and p.role='manager' and p.department_id=deviations.department_id));
create policy "employee create deviation" on deviations for insert with check (created_by=auth.uid());
create policy "quality update deviation" on deviations for update using (exists(select 1 from profiles p where p.id=auth.uid() and p.role in ('quality','admin')));
create policy "own notifications" on notifications for select using(user_id=auth.uid());
create or replace function prevent_closed_deviation_delete() returns trigger language plpgsql as $$ begin if old.status='Закрыто' then raise exception 'Closed deviations cannot be deleted'; end if; return old; end $$;
create trigger no_closed_deviation_delete before delete on deviations for each row execute function prevent_closed_deviation_delete();
